mapper.select:
SELECT id, hazard_no AS hazardNo, tunnel_id AS tunnelId, section_id AS sectionId,
       hazard_type AS hazardType, event_time AS eventTime, position, consequence,
       level, relate_event_id AS relateEventId, patrol_hazard_id AS patrolHazardId,
       register_user_id AS registerUserId, remark
FROM warn_hazard_event
WHERE tunnel_id = #{tunnelId}

  AND hazard_type = #{hazardType}


  AND event_time >= #{from}


  AND event_time <= #{to}

ORDER BY event_time DESC
